export const addProductionEntry = (
  itemId: MaybeRefOrGetter<string>,
  productionEntryForm?: MaybeRefOrGetter<ProductionEntryForm>,
  options?: SecondParameter<typeof apiRequest>,
  signal?: AbortSignal,
) => {
  itemId = toValue(itemId)
  productionEntryForm = toValue(productionEntryForm)
  const formData = new FormData()
  if (productionEntryForm?.id !== undefined) {
    formData.append(`id`, productionEntryForm.id)
  }
  if (productionEntryForm?.day !== undefined) {
    formData.append(`day`, productionEntryForm.day)
  }
  if (productionEntryForm?.quantity !== undefined) {
    formData.append(`quantity`, productionEntryForm.quantity.toString())
  }
  if (productionEntryForm?.workerCount !== undefined && productionEntryForm.workerCount !== null) {
    formData.append(`workerCount`, productionEntryForm.workerCount.toString())
  }
  if (productionEntryForm?.note !== undefined && productionEntryForm.note !== null) {
    formData.append(`note`, productionEntryForm.note)
  }
  if (productionEntryForm?.onField !== undefined) {
    formData.append(`onField`, productionEntryForm.onField.toString())
  }
  if (productionEntryForm?.files !== undefined && productionEntryForm.files !== null) {
    productionEntryForm?.files.forEach((value) => formData.append(`files`, value))
  }

  return apiRequest<ProductionEntryView>(
    {
      url: `/api/production/items/${itemId}/entries`,
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      data: formData,
      signal,
    },
    options,
  )
}

